  "model": "openai/gpt-4o-mini",
  "input": "Use the code_exec tool to run: print(\"hello\")",
  "tools": [
    {
      "type": "custom",
      "name": "code_exec",
      "description": "Executes arbitrary python code",
      "format": {
        "type": "text"
      }
    }
  ],
  "tool_choice": {
    "type": "custom",
    "name": "code_exec"
  },
  "max_output_tokens": 256,
  "stream": true
}

{
  "model": "openai/gpt-4o-mini",
  "include": [
    "reasoning.encrypted_content"
  ],
  "store": false,
  "tool_choice": {
    "type": "custom",
    "name": "exec"
  },
  "max_output_tokens": 256,
  "input": [
    {
      "type": "additional_tools",
      "id": "at_harness_189_3",
      "role": "developer",
      "tools": [
        {
          "type": "namespace",
          "name": "functions",
          "description": "",
          "tools": [
            {
              "type": "custom",
              "name": "exec",
              "description": "Run JavaScript code",
              "format": {
                "type": "grammar",
                "syntax": "lark",
                "definition": "start: /[\\s\\S]+/"
              }
            },
            {
              "type": "function",
              "name": "wait",
              "description": "Waits on a running exec cell.",
              "strict": false,
              "parameters": {
                "type": "object",
                "properties": {
                  "cell_id": {
                    "type": "string"
                  }
                },
                "required": [
                  "cell_id"
                ],
                "additionalProperties": false
              }
            }
          ]
        },
        {
          "type": "namespace",
          "name": "clock",
          "description": "Tools for reading and waiting on time.",
          "tools": [
            {
              "type": "function",
              "name": "sleep",
              "description": "Pause execution.",
              "strict": false,
              "parameters": {
                "type": "object",
                "properties": {
                  "duration_ms": {
                    "type": "number"
                  }
                },
                "required": [
                  "duration_ms"
                ],
                "additionalProperties": false
              }
            }
          ]
        }
      ]
    },
    {
      "type": "message",
      "role": "user",
      "content": [
        {
          "type": "input_text",
          "text": "Use exec to run: console.log(1)"
        }
      ]
    }
  ]
}
